    static if (allTestsEnabled)
    {
        // Single letter identical strands
        assert(distance("A", "A") == 0);

        // Single letter different strands
        assert(distance("G", "T") == 1);

        // Long identical strands
        assert(distance("GGACTGAAATCTG", "GGACTGAAATCTG") == 0);

        // Long different strands
        assert(distance("GGACGGATTCTG", "AGGACGGATTCT") == 9);

        // Disallow first strand longer 
        assertThrown(distance("AATG", "AAA"));

        // Disallow second strand longer
        assertThrown(distance("AAA", "AGTG"));

        // Disallow left empty strand
        assertThrown(distance("", "G"));

        // Disallow right empty strand
        assertThrown(distance("G", ""));
    }

}

example_solution:
module hamming;

import std.string;
import std.algorithm.comparison : mismatch;
import std.exception : enforce;

pure int distance(immutable string lhs, immutable string rhs)
{
    enforce(lhs.length == rhs.length, "left and right strands must be of equal length");

    int count = 0;
    auto m = mismatch(lhs, rhs);

    while (!m[0].empty)
    {
        ++count;
        m = mismatch(m[0][1 .. $], m[1][1 .. $]);
    }

    return count;
}

